mapper.select:
select s.id,s.content,s.create_at, s.image,s.is_see,s.send_state, s.send_time,s.`state`,s.title, s.url,s.`type`,s.platform, s.user_id,u2.user_name as userName,s.audit_content, s.status,s.by_user_id,s.platform_id, s.shop_id,s.data_id,s.phone,u.user_name as byUserName from message_info s left join tb_user u on s.by_user_id=u.user_id left join tb_user u2 on s.user_id=u2.user_id
and s.`state`=#{state}
order by s.id desc

